245	            <div className="flex items-center justify-between text-sm">
246	              <span className="text-muted-foreground">
247	                Step {Math.min(displayStep + 1, totalSteps)} of {totalSteps}
248	              </span>
249	              <span className="tabular-nums font-medium text-foreground">{Math.min(progressPercent, 100)}%</span>
250	            </div>

